1	import net from "node:net";
2	
3	/**
4	 * Dependency-free, in-memory sliding-window rate limiter.
5	 *
6	 * Suitable for single-process app-level throttling (login attempts, etc).
7	 * State lives in a module-level Map; on a horizontally-scaled deployment each
8	 * instance limits independently — acceptable for auth-abuse mitigation. A
9	 * background sweep prunes empty buckets so the Map does not grow unbounded.
10	 */
11	
12	type Bucket = number[]; // sorted-ish list of hit timestamps (ms)
13	
14	const buckets = new Map<string, Bucket>();
15	
16	// Persist the Map across HMR / route reloads in dev.
17	const globalForRl = globalThis as unknown as { __nxeonRateLimit?: Map<string, Bucket> };
18	const store: Map<string, Bucket> = globalForRl.__nxeonRateLimit ?? buckets;
19	if (process.env.NODE_ENV !== "production") globalForRl.__nxeonRateLimit = store;
20	
21	export type RateLimitOptions = { max: number; windowMs: number };
22	export type RateLimitResult = { ok: boolean; retryAfterSec: number; remaining: number };
23	
24	/**
25	 * The widest window any caller has ever asked for.
26	 *
27	 * The sweep below used a HARDCODED 15-minute horizon while callers pass windows
28	 * far longer than that — `RESEND_LIMIT` in lib/email-verification.ts is an hour,
29	 * as are the mail-send, calendar-mutation, org-invite and wallet-top-up limits.
30	 * A bucket whose last hit was 16 minutes ago was therefore DELETED, and deleting
31	 * a bucket resets its counter: "5 verification emails per hour" was really "5
32	 * per 15 minutes, forever", and "60 outbound mails per hour" was 60 per quarter
33	 * hour. The limiter silently enforced a limit nobody had chosen, and the longer
34	 * the window a caller asked for, the less of it was honoured.
35	 *
36	 * Tracking the real maximum keeps the sweep's only job — bounding the Map — from
37	 * quietly becoming a policy decision. It only ever grows, so it can never evict a
38	 * bucket that some caller still considers live.
39	 */
40	let widestWindowMs = 15 * 60 * 1000;
41	
42	/**
43	 * Record and check a hit for `key`. Returns `{ ok, retryAfterSec, remaining }`.
44	 * When `ok` is false the caller should reject and surface `retryAfterSec`.
45	 */
46	export function checkRateLimit(key: string, { max, windowMs }: RateLimitOptions): RateLimitResult {
47	  const now = Date.now();
48	  if (windowMs > widestWindowMs) widestWindowMs = windowMs;
49	  sweep(now);
50	  const cutoff = now - windowMs;
51	  const hits = (store.get(key) ?? []).filter((t) => t > cutoff);
52	
53	  if (hits.length >= max) {
54	    const oldest = hits[0];
55	    const retryAfterSec = Math.max(1, Math.ceil((oldest + windowMs - now) / 1000));
56	    store.set(key, hits); // persist the pruned window
57	    return { ok: false, retryAfterSec, remaining: 0 };
58	  }
59	
60	  hits.push(now);
61	  store.set(key, hits);
62	  return { ok: true, retryAfterSec: 0, remaining: max - hits.length };
63	}
64	
65	/** Clear the window for a key (e.g. after a successful login). */
66	export function resetRateLimit(key: string): void {
67	  store.delete(key);
68	}
69	
70	/**
71	 * Preset for login throttling: 5 attempts per 15 minutes per identifier.
72	 * Pass a stable identifier such as `${email}:${ip}`.
73	 */
74	export function loginRateLimit(identifier: string): RateLimitResult {
75	  return checkRateLimit(`login:${identifier}`, { max: 5, windowMs: 15 * 60 * 1000 });
76	}
77	
78	// Opportunistic sweep of fully-expired buckets (runs at most once/min, no timer).
79	let lastSweep = 0;
80	function sweep(now: number) {
81	  if (now - lastSweep < 60_000) return;
82	  lastSweep = now;
83	  for (const [key, hits] of store) {
84	    if (hits.length === 0 || hits[hits.length - 1] < now - widestWindowMs) store.delete(key);
85	  }
86	}
87	
88	/* -------------------------------------------------------------------------- */
89	/*                       Who is being rate limited                            */
90	/* -------------------------------------------------------------------------- */
91	
92	/**
93	 * How many reverse proxies sit in front of this app and append to
94	 * `X-Forwarded-For`. ONE (nginx) for every current Nxeon deployment.
95	 *
96	 * Raise it only when you actually add another trusted hop (a CDN in front of
97	 * nginx). Setting it higher than the number of proxies you really run walks the
98	 * trusted suffix backwards into entries the CLIENT wrote, which is the exact bug
99	 * this function exists to fix. Setting it lower behind a CDN collapses every
100	 * visitor onto the edge's address, which turns a per-attacker throttle into a
101	 * global one — a login lockout for every customer at once.
102	 */
103	const TRUSTED_PROXY_HOPS = Math.max(1, Number(process.env.NXEON_TRUSTED_PROXY_HOPS ?? 1) || 1);
104	
105	/** `unknown` is the shared bucket for callers we cannot place. */
106	export const UNKNOWN_IP = "unknown";
107	
108	/**
109	 * Strip an optional `:port` / `[v6]:port` wrapper and an IPv4-mapped IPv6 prefix
110	 * so the same peer always produces the same bucket key. `::ffff:127.0.0.1` and
111	 * `127.0.0.1` are one machine; without this they are two budgets.
112	 */
113	function normaliseAddress(value: string): string {
114	  let v = value.trim();
115	  if (v.startsWith("[")) {
116	    const end = v.indexOf("]");
117	    if (end !== -1) v = v.slice(1, end);
118	  } else if (v.includes(":") && net.isIP(v) === 0) {
119	    // host:port for IPv4 (a bare IPv6 has many colons and parses as an IP).
120	    v = v.split(":")[0];
121	  }
122	  const mapped = /^::ffff:((?:\d{1,3}\.){3}\d{1,3})$/i.exec(v);
123	  return mapped ? mapped[1] : v;
124	}
125	
126	/** Anything with a `.get()`: `await headers()`, `req.headers`, or a `Request`. */
127	type HeaderLike = { get(name: string): string | null };
128	export type ClientIpSource = HeaderLike | { headers: HeaderLike };
129	
130	function headersOf(source: ClientIpSource): HeaderLike {
131	  return typeof (source as HeaderLike)?.get === "function"
132	    ? (source as HeaderLike)
133	    : (source as { headers: HeaderLike }).headers;
134	}
135	
136	/**
137	 * The caller's address, for use as a rate-limit key. NEVER attacker-controlled.
138	 *
139	 * ── THIS IS THE ONLY DEFINITION ──────────────────────────────────────────────
140	 *
141	 * There were two. This one owned the trusted-hop knob; `trustedClientIp` in
142	 * app/api/_lib/client-ip.ts owned IP-format validation and `::ffff:`/port
143	 * normalisation. Each was correct about something the other got wrong, they were
144	 * written days apart from the same incident, and a reader had no way to know
145	 * which one their call site should use. A second definition of an existing thing
146	 * is this repo's most common defect class and it caused two production bugs in
147	 * one week, so the two have been merged here and `trustedClientIp` is now an
148	 * alias for this function — same code, two names, because ~15 route handlers
149	 * import it under the second one.
150	 *
151	 * Accepts a `Request` as well as a headers object so route handlers and server
152	 * actions call the same function rather than each growing a wrapper.
153	 *
154	 * WHY THIS IS NOT `xff.split(",")[0]`, which is what every call site used to do
155	 * (and what two route handlers still described in a comment as "the real
156	 * client"). nginx forwards the header as:
157	 *
158	 *     proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
159	 *
160	 * and `$proxy_add_x_forwarded_for` expands to `$http_x_forwarded_for,
161	 * $remote_addr` — it APPENDS the peer it actually saw to whatever the client
162	 * sent. So the header this app receives is:
163	 *
164	 *     <anything the client typed>, <the client's real address>
165	 *
166	 * The LEFTMOST entry is therefore not the client, it is a free-text field the
167	 * client filled in. Reading it made every limiter keyed on "the IP" evadable by
168	 * sending a different fake value each request — and that is not a theoretical
169	 * grading of a header, it was measured: 25 requests through the real nginx with a
170	 * rotating `X-Forwarded-For` never once tripped a limit that a fixed value trips
171	 * on the 21st. The same expression keyed the login throttle, so the lockout that
172	 * is supposed to stop password AND 2FA guessing against a named account stopped
173	 * nothing. It also keyed the row `POST /api/track` stores as a visitor's IP, so
174	 * the address in the admin visitor log is whatever the visitor chose to claim.
175	 *
176	 * The trustworthy entry is the one NGINX appended: the last one. Everything to
177	 * its left is client-authored and is discarded. `x-real-ip` (set by the same
178	 * vhosts with `proxy_set_header X-Real-IP $remote_addr`, which REPLACES rather
179	 * than appends) is an equally sound second source and is used when no
180	 * X-Forwarded-For arrives at all.
181	 *
182	 * Accepts anything with a `.get()` — `await headers()` from a server action,
183	 * `req.headers`, or the `Request` itself — so there is ONE definition of "who is
184	 * calling" rather than a copy per call site that can drift.
185	 *
186	 * Every candidate is VALIDATED as an IP before it is returned. A header that is
187	 * not an address is not an identity, and letting one through means an attacker
188	 * picks their own bucket name by sending garbage — the same defeat as reading
189	 * the first hop, one step removed. When nothing checks out the caller falls into
190	 * the shared `UNKNOWN_IP` bucket, which is conservative rather than private.
191	 *
192	 * DEPLOYMENT COUPLING: correct for exactly `TRUSTED_PROXY_HOPS` reverse proxies
193	 * in front of the app. If a CDN is ever added, raise that env var; the fix is
194	 * never to go back to reading the leftmost hop.
195	 */
196	export function clientIp(source: ClientIpSource): string {
197	  const h = headersOf(source);
198	  const hops = (h.get("x-forwarded-for") ?? "")
199	    .split(",")
200	    .map((s) => s.trim())
201	    .filter(Boolean);
202	  if (hops.length > 0) {
203	    // Walk back past the proxies we run. Clamped at 0 so a misconfigured hop
204	    // count degrades to "the leftmost entry" instead of throwing, and keep
205	    // walking left while the entry is not a valid address — a junk value at the
206	    // trusted position must not become a bucket key of its own.
207	    for (let i = Math.max(0, hops.length - TRUSTED_PROXY_HOPS); i >= 0; i--) {
208	      const candidate = normaliseAddress(hops[i]);
209	      if (net.isIP(candidate) !== 0) return candidate;
210	    }
211	  }
212	  // `x-real-ip` is set with `proxy_set_header X-Real-IP $remote_addr`, which
213	  // REPLACES any client value rather than appending — an equally sound source.
214	  const real = normaliseAddress(h.get("x-real-ip") ?? "");
215	  if (net.isIP(real) !== 0) return real;
216	  return UNKNOWN_IP;
217	}
