import type { Client, ClientChannel } from "ssh2";
import { db } from "/opt/nxeon-wt-roles/lib/db";
import { withServerSsh, shellQuote } from "/opt/nxeon-wt-roles/lib/ssh-exec";
import { rconPasswordFor } from "/opt/nxeon-wt-roles/lib/free-minecraft-control";

const CONTAINER = "mc-rolestest";
const OWNER_ID = "rolestest-owner";

function interactiveExec(conn: Client, command: string, lines: string[], delayMs: number, totalTimeoutMs: number): Promise<string> {
  return new Promise((resolve, reject) => {
    conn.exec(command, (err, stream: ClientChannel) => {
      if (err) return reject(err);
      let out = "";
      const timer = setTimeout(() => {
        try { stream.close(); } catch {}
        resolve(out + "\n[TIMEOUT]");
      }, totalTimeoutMs);
      stream.on("close", () => { clearTimeout(timer); resolve(out); });
      stream.on("data", (d: Buffer) => (out += d.toString("utf8")));
      stream.stderr.on("data", (d: Buffer) => (out += "[STDERR]" + d.toString("utf8")));

      (async () => {
        for (const line of lines) {
          stream.write(line + "\n");
          await new Promise((r) => setTimeout(r, delayMs));
        }
        stream.write("exit\n");
      })();
    });
  });
}

async function main() {
  const host = await db.server.findFirst({
    where: { hostname: "freemc-host" },
    select: { id: true, rootPassword: true, rootPasswordEnc: true, sshPort: true, dedicatedIp: { select: { address: true } } },
  });
  if (!host) throw new Error("no host");

  await withServerSsh(host, async (conn) => {
    const password = rconPasswordFor(OWNER_ID);
    const cmd = `docker exec -i ${shellQuote(CONTAINER)} env RCON_PASSWORD=${shellQuote(password)} rcon-cli`;
    const out = await interactiveExec(conn, cmd, ["lp listgroups"], 4000, 15_000);
    console.log("=== interactive session output ===");
    console.log(out);
  });
  process.exit(0);
}

main().catch((e) => {
  console.error("FAILED", e);
  process.exit(1);
});

