import { db } from "/opt/nxeon-wt-roles/lib/db";
import { withServerSsh, exec, shellQuote } from "/opt/nxeon-wt-roles/lib/ssh-exec";
import { rconPasswordFor } from "/opt/nxeon-wt-roles/lib/free-minecraft-control";

const CONTAINER = "mc-rolestest";
const OWNER_ID = "rolestest-owner";

async function main() {
  const host = await db.server.findFirst({
    where: { hostname: "freemc-host" },
    select: { id: true, rootPassword: true, rootPasswordEnc: true, sshPort: true, dedicatedIp: { select: { address: true } } },
  });
  if (!host) throw new Error("no host");

  const cmds = process.argv.slice(2);

  await withServerSsh(host, async (conn) => {
    if (cmds[0] === "--status") {
      const r = await exec(conn, `docker inspect -f '{{.State.Running}}' ${shellQuote(CONTAINER)}`, 10_000);
      console.log("running:", r.stdout.trim(), r.stderr);
      const logs = await exec(conn, `docker logs --tail 40 ${shellQuote(CONTAINER)}`, 10_000);
      console.log("--- logs tail ---\n", logs.stdout, logs.stderr);
      return;
    }
    for (const c of cmds) {
      const password = rconPasswordFor(OWNER_ID);
      const r = await exec(
        conn,
        `docker exec ${shellQuote(CONTAINER)} env RCON_PASSWORD=${shellQuote(password)} rcon-cli ${shellQuote(c)}`,
        15_000,
      );
      console.log(`>>> ${c}\ncode=${r.code}\nstdout=${r.stdout}\nstderr=${r.stderr}\n---`);
    }
  });
  process.exit(0);
}

main().catch((e) => {
  console.error("FAILED", e);
  process.exit(1);
});

