"use server";

/**
 * Roles & command-permissions for plugin-based free Minecraft servers, backed
 * entirely by LuckPerms (bundled on every `kind:"plugins"` FREEMC_PRESETS
 * entry — see lib/free-minecraft-control.ts). No new DB schema: LuckPerms owns
 * all role/permission state itself, inside the container, in its own
 * storage — every read below is a LIVE query against that storage, nothing is
 * cached or mirrored into Postgres.
 *
 * ============================================================================
 * WHY READS GO THROUGH FILES, NOT RCON TEXT — READ THIS BEFORE CHANGING IT
 * ============================================================================
 * The obvious design (mirroring lib/free-minecraft-control.ts's sendRcon +
 * text-parsing pattern used everywhere else) is to run `/lp listgroups`,
 * `/lp group X permission info`, `/lp group X listmembers`, etc. over RCON
 * and parse the text response, the same way getFreeServerPlayers parses
 * `list`'s output. That was the ORIGINAL plan here — it does not work, and
 * this was proven with a real container (`mc-rolestest` on freemc-host,
 * itzg/minecraft-server, Paper 26.1.2, LuckPerms v5.5.71), not assumed:
 *
 *   - `/lp creategroup vip`, `/lp group X permission set ...`, `/lp user X
 *     parent add ...` etc. ALL return a completely EMPTY RCON response —
 *     every time, regardless of storage backend (tested against both LP's
 *     default H2 storage and yaml flat-file storage) and regardless of how
 *     long the RCON connection is kept open afterward (tested with an
 *     interactive rcon-cli session held open 4s+ past the command — still
 *     nothing).
 *   - Crucially, the commands DO still execute — confirmed by reading
 *     LuckPerms' own storage back after each one (the group/user file exists,
 *     with exactly the right permissions/parents). So this is not a broken
 *     feature, it is a broken CONFIRMATION CHANNEL: LuckPerms dispatches its
 *     command handling through its own internal thread pool, and whatever it
 *     sends back to the CommandSender arrives after Bukkit's RCON dispatch
 *     has already returned an (empty) response and torn down the feedback
 *     collector for that invocation. Nothing ever reaches the RCON socket,
 *     and nothing is logged to console either — the reply is just discarded.
 *   - This is specific to LuckPerms' own `/lp ...` command family. Plain
 *     synchronous commands on the SAME container (vanilla `list`/`seed`,
 *     Paper's `/plugins`, Essentials' `/balance`+`/eco give` argument-error
 *     paths) all return real text over the identical RCON path — so this is
 *     not a general RCON/plugin problem, it is specific to LP's async command
 *     execution model.
 *
 * So: MUTATIONS still go over RCON (sendRcon from free-minecraft-control.ts —
 * fire and forget, no text to parse), but every READ in this file — listing
 * roles, their granted nodes, their members — parses LuckPerms' own on-disk
 * storage directly over SSH (`cat`), which is fast, reliable, and exactly
 * "live" (nothing cached). After a mutation, this file always reads the
 * relevant file straight back to report real success/failure to the caller,
 * rather than trusting RCON's silence.
 *
 * That in turn requires LuckPerms be configured with flat-file (`yaml`)
 * storage rather than its H2-database default — an H2 file isn't something
 * this app can parse without a JDBC driver — and, separately, with
 * `use-server-uuid-cache: true`. That second one is its own confirmed
 * finding: with LuckPerms' DEFAULT config (`use-server-uuid-cache: false`),
 * `/lp user <name> parent add <group>` for a player who has NEVER joined
 * silently does nothing at all — no user file is ever created. Flipping that
 * one config key fixed it immediately (verified: the resulting user file
 * appears, keyed by the standard offline-mode UUID — see offlineUuidFor
 * below, whose output was checked byte-for-byte against what LuckPerms
 * itself produced for the same username). Without this, "assign a role by
 * username without requiring the player to be online" — an explicit
 * requirement here — would only work for players who had already connected
 * at least once, which defeats the point.
 *
 * ensureLuckPermsReady() below applies both settings idempotently (a cheap
 * `cat` + regex check first; only sed+restarts the container the first time
 * a given container actually needs it). Note this can also need to re-fire
 * after a PRESET SWITCH: applyFreeMinecraftPreset (lib/actions-free-minecraft.ts,
 * off-limits to this feature) wipes `/data/plugins/*` on every preset change,
 * which deletes LuckPerms' whole config+storage along with it — so config
 * drifting back to defaults after a preset switch is expected, not a bug,
 * and this file re-detects and re-applies every time rather than assuming a
 * one-time fix sticks forever.
 *
 * ============================================================================
 * WHAT WASN'T POSSIBLE TO VERIFY, AND WHY — SEE lib/freemc-command-catalog.ts
 * ============================================================================
 * True in-game "grant nothing, confirm the command is actually denied"
 * testing could not be done here, for two structural reasons documented in
 * detail in freemc-command-catalog.ts's header: RCON always runs as a
 * permission-bypassing console sender (so an RCON-issued command can never be
 * observed being denied, no matter what LuckPerms says), and no real
 * Minecraft client library exists for this environment's protocol version.
 * The command catalog was instead verified against the actual bundled
 * EssentialsX jar's declared commands + in-jar permission-node strings, which
 * caught a real error in the assumed `essentials.command.<cmd>` convention —
 * see that file.
 */
import { revalidatePath } from "next/cache";
import type { User } from "@prisma/client";
import { db } from "./db";
import { requireUser } from "./auth";
import { checkRateLimit } from "./rate-limit";
import { withServerSsh, exec, shellQuote } from "./ssh-exec";
import type { SftpServer } from "./sftp";
import { sendRcon, FREEMC_PRESETS } from "./free-minecraft-control";
import { FREEMC_GATEABLE_COMMANDS, isGateableCommandNode } from "./freemc-command-catalog";
import { createHash } from "node:crypto";

type Result = { error?: string };

// A LuckPerms group name we create. LP itself lowercases group names
// internally regardless of what's typed at it — requiring lowercase input
// here (rather than silently normalizing) keeps what the customer typed, what
// we send to RCON, and what we read back off disk all identical, with no
// hidden normalization step that could make a "role already exists" check
// miss a case-variant collision.
const ROLE_NAME_RE = /^[a-z][a-z0-9_]{2,19}$/;
// LuckPerms' own built-in group that every player starts in — never
// customer-managed here (deleting it, or hiding permissions on it, would
// affect literally every player on the server, not just people the owner
// deliberately assigned).
const RESERVED_ROLE_NAMES = new Set(["default"]);
// Standard Minecraft username shape (Mojang's own constraint), exactly as
// specified for this feature — deliberately NOT the broader
// game-control.ts validatePlayerId shape, which also allows SteamIDs/colons
// for other games' player identifiers.
const PLAYER_NAME_RE = /^[A-Za-z0-9_]{3,16}$/;

/** The dedicated Docker host — duplicated in miniature from
 *  lib/actions-free-minecraft.ts's freemcHost() (not exported there, and
 *  that file is off-limits for this feature to edit). Keep in sync if the
 *  Server row shape it selects ever changes. */
async function freemcHost(): Promise<SftpServer> {
  const host = await db.server.findFirst({
    where: { hostname: "freemc-host" },
    select: { id: true, rootPassword: true, rootPasswordEnc: true, sshPort: true, dedicatedIp: { select: { address: true } } },
  });
  if (!host) throw new Error("Free Minecraft host is not provisioned.");
  return host;
}

/** Loads the caller's free server and confirms it's on a plugins-kind preset
 *  (LuckPerms only runs there — see FREEMC_PRESETS). `db.freeMinecraftServer
 *  .findUnique({ where: { userId } })` IS the ownership check, same pattern
 *  every other free-Minecraft action in this codebase uses: a row can only
 *  ever be found under the caller's own userId. */
async function requireOwnedPluginServer(
  user: User,
): Promise<{ ok: true; row: { id: string; containerName: string; preset: string } } | { ok: false; error: string }> {
  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
  if (!row) return { ok: false, error: "You don't have a free server." };
  const preset = FREEMC_PRESETS[row.preset];
  if (!preset || preset.kind !== "plugins") {
    return { ok: false, error: "Roles are available on plugin-based game modes only — switch presets first." };
  }
  return { ok: true, row };
}

// ---------------------------------------------------------------------------
// LuckPerms on-disk storage — paths, config bootstrap, tiny YAML-lite parser
// ---------------------------------------------------------------------------

const LP_DIR = "/data/plugins/LuckPerms";
const LP_CONFIG = `${LP_DIR}/config.yml`;
const LP_GROUPS_DIR = `${LP_DIR}/yaml-storage/groups`;
const LP_USERS_DIR = `${LP_DIR}/yaml-storage/users`;

/**
 * Idempotently makes sure a container's LuckPerms is configured the way this
 * feature needs (yaml storage + use-server-uuid-cache: true — see the big
 * comment at the top of this file for why both are required). Only
 * sed+restarts the container when the config doesn't already match; a
 * container fixed once stays fixed until something else (a preset switch)
 * wipes its plugin data.
 */
async function ensureLuckPermsReady(
  conn: Parameters<typeof exec>[0],
  containerName: string,
): Promise<{ ok: true } | { ok: false; error: string }> {
  const read = await exec(conn, `docker exec ${shellQuote(containerName)} cat ${shellQuote(LP_CONFIG)}`, 10_000);
  if (read.code !== 0) {
    return { ok: false, error: "LuckPerms hasn't finished starting up yet — try again in a moment." };
  }
  const hasYaml = /^storage-method:\s*yaml\s*$/m.test(read.stdout);
  const hasUuidCache = /^use-server-uuid-cache:\s*true\s*$/m.test(read.stdout);
  if (hasYaml && hasUuidCache) return { ok: true };

  const sed = await exec(
    conn,
    `docker exec ${shellQuote(containerName)} sed -i ` +
      `-e 's/^storage-method:.*/storage-method: yaml/' ` +
      `-e 's/^use-server-uuid-cache:.*/use-server-uuid-cache: true/' ` +
      `${shellQuote(LP_CONFIG)}`,
    10_000,
  );
  if (sed.code !== 0) {
    return { ok: false, error: "Couldn't prepare roles for your server — please try again." };
  }

  const restart = await exec(conn, `docker restart ${shellQuote(containerName)}`, 30_000);
  if (restart.code !== 0) {
    return { ok: false, error: "Couldn't restart your server to apply roles setup — please try again." };
  }

  // Poll for RCON to come back up rather than assuming a fixed boot time —
  // plugin containers on a warm cache (jars already downloaded, world
  // already generated) came back in under a minute in testing, but that's
  // not a hard guarantee under load.
  for (let i = 0; i < 18; i++) {
    await new Promise((r) => setTimeout(r, 5_000));
    const probe = await sendRcon(conn, containerName, "freemc-roles-bootstrap", "list").catch(() => null);
    if (probe?.ok) return { ok: true };
  }
  return { ok: false, error: "Your server is taking longer than usual to restart — try again shortly." };
}

/**
 * Minecraft's standard OFFLINE-mode player UUID: MD5("OfflinePlayer:" + name)
 * with the version/variant bits patched to a v3 UUID — the exact algorithm
 * Java's `UUID.nameUUIDFromBytes` performs, and LuckPerms is confirmed (byte-
 * for-byte, against a real never-joined test player) to derive the same UUID
 * for a username it has no cached record for once use-server-uuid-cache is
 * on. Used here only to know which yaml-storage/users file to expect after a
 * `parent add`/`parent remove` — never sent anywhere, never trusted as an
 * identity check.
 */
function offlineUuidFor(name: string): string {
  const hash = createHash("md5").update(`OfflinePlayer:${name}`, "utf8").digest();
  hash[6] = (hash[6] & 0x0f) | 0x30;
  hash[8] = (hash[8] & 0x3f) | 0x80;
  const hex = hash.toString("hex");
  return [hex.slice(0, 8), hex.slice(8, 12), hex.slice(12, 16), hex.slice(16, 20), hex.slice(20)].join("-");
}

type ParsedLpFile = { name: string | null; uuid: string | null; permissions: string[]; parents: string[] };

/**
 * Minimal parser for LuckPerms' yaml-storage group/user files. Not a general
 * YAML parser — deliberately narrow, matching exactly the flat shape LP
 * itself writes (confirmed live): a handful of top-level `key: value` scalars
 * (`name`, `uuid`, `primary-group`) plus two possible list sections,
 * `permissions:` and `parents:`, each either a bare `- node` (implicitly
 * granted/true) or a negated `- node:` line followed by an indented
 * `    value: false` line (both forms were produced live and are handled).
 */
function parseLuckPermsFile(text: string): ParsedLpFile {
  const lines = text.split("\n").map((l) => l.replace(/\r$/, ""));
  let name: string | null = null;
  let uuid: string | null = null;
  const permissions: string[] = [];
  const parents: string[] = [];
  let section: "none" | "permissions" | "parents" = "none";

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (line === "") continue;

    const isTopLevelKey = /^[A-Za-z-]+:/.test(line);
    if (isTopLevelKey) {
      if (/^name:/.test(line)) name = line.slice(5).trim().replace(/^'(.*)'$/, "$1");
      else if (/^uuid:/.test(line)) uuid = line.slice(5).trim();
      section = /^permissions:\s*$/.test(line) ? "permissions" : /^parents:\s*$/.test(line) ? "parents" : "none";
      continue;
    }

    const negatedHead = line.match(/^-\s+(\S+):\s*$/);
    const bare = line.match(/^-\s+(\S+)\s*$/);
    if (section === "permissions") {
      if (negatedHead) {
        const next = lines[i + 1] ?? "";
        const valMatch = next.match(/^\s+value:\s*(true|false)\s*$/);
        if (valMatch) i++; // consume the lookahead line either way
        if (valMatch?.[1] === "true") permissions.push(negatedHead[1]);
      } else if (bare) {
        permissions.push(bare[1]);
      }
    } else if (section === "parents" && bare) {
      parents.push(bare[1]);
    }
  }
  return { name, uuid, permissions, parents };
}

/** Reads every `*.yml` file in a yaml-storage subdirectory in one round trip
 *  (one `cat`, not N), returning `{ key, text }` per file — `key` is the
 *  filename without `.yml` (a group name, or a user's UUID). */
async function readYamlStorageDir(
  conn: Parameters<typeof exec>[0],
  containerName: string,
  dir: string,
): Promise<{ key: string; text: string }[]> {
  const MARK = "===FREEMC_ROLES_FILE:";
  const cmd =
    `docker exec ${shellQuote(containerName)} sh -c ` +
    shellQuote(
      `d=${dir}; [ -d "$d" ] || exit 0; for f in "$d"/*.yml; do [ -f "$f" ] || continue; ` +
        `echo "${MARK}$(basename "$f" .yml)==="; cat "$f"; done`,
    );
  const r = await exec(conn, cmd, 15_000);
  if (r.code !== 0 || !r.stdout.trim()) return [];
  const out: { key: string; text: string }[] = [];
  const parts = r.stdout.split(new RegExp(`^${MARK}(.+?)===$`, "m"));
  // parts[0] is anything before the first marker (empty); then alternating [key, text, key, text, ...]
  for (let i = 1; i < parts.length; i += 2) {
    out.push({ key: parts[i], text: parts[i + 1] ?? "" });
  }
  return out;
}

export type FreemcRoleMember = { uuid: string; name: string | null };
export type FreemcRole = { name: string; permissions: string[]; members: FreemcRoleMember[] };

/** Live read of every customer-manageable role (LuckPerms group, excluding
 *  the built-in `default`), each with its currently granted gateable
 *  permission nodes and its members. */
export async function listFreemcRoles(): Promise<{ ok: true; roles: FreemcRole[] } | { ok: false; error: string }> {
  const user = await requireUser();
  const owned = await requireOwnedPluginServer(user);
  if (!owned.ok) return { ok: false, error: owned.error };

  try {
    const host = await freemcHost();
    const roles = await withServerSsh(host, async (conn) => {
      const [groupFiles, userFiles] = await Promise.all([
        readYamlStorageDir(conn, owned.row.containerName, LP_GROUPS_DIR),
        readYamlStorageDir(conn, owned.row.containerName, LP_USERS_DIR),
      ]);
      const users = userFiles.map(({ key, text }) => ({ uuid: key, ...parseLuckPermsFile(text) }));

      return groupFiles
        .filter(({ key }) => !RESERVED_ROLE_NAMES.has(key))
        .map(({ key, text }) => {
          const parsed = parseLuckPermsFile(text);
          const members: FreemcRoleMember[] = users
            .filter((u) => u.parents.includes(key))
            .map((u) => ({ uuid: u.uuid, name: u.name && u.name !== "null" ? u.name : null }));
          return { name: key, permissions: parsed.permissions.filter(isGateableCommandNode), members };
        });
    });
    return { ok: true, roles };
  } catch (e) {
    console.error("[freemc-roles] list failed:", e);
    return { ok: false, error: "Couldn't reach your server — is it asleep? Connect first to wake it up." };
  }
}

// ---------------------------------------------------------------------------
// Mutations — RCON write, then read the same file straight back to confirm
// ---------------------------------------------------------------------------

/** Small retry helper: LuckPerms' RCON write returns before its async
 *  command actually finishes (see top-of-file note), so the file we read
 *  back to confirm a mutation can very briefly not exist/not be updated yet.
 *  In testing this never took more than one tick, but this isn't guaranteed
 *  under load, so poll a few times rather than assume. */
async function pollUntil<T>(fn: () => Promise<T>, isDone: (v: T) => boolean, attempts = 5, delayMs = 400): Promise<T> {
  let last: T;
  for (let i = 0; i < attempts; i++) {
    last = await fn();
    if (isDone(last)) return last;
    if (i < attempts - 1) await new Promise((r) => setTimeout(r, delayMs));
  }
  return last!;
}

export async function createFreemcRole(_prev: unknown, formData: FormData): Promise<Result> {
  const user = await requireUser();
  const owned = await requireOwnedPluginServer(user);
  if (!owned.ok) return { error: owned.error };

  const rl = checkRateLimit(`freemc:roles:create:${user.id}`, { max: 10, windowMs: 60_000 });
  if (!rl.ok) return { error: `Too many attempts — try again in ${rl.retryAfterSec}s.` };

  const name = String(formData.get("name") ?? "").trim().toLowerCase();
  if (!ROLE_NAME_RE.test(name) || RESERVED_ROLE_NAMES.has(name)) {
    return { error: "Role names: 3-20 lowercase letters, numbers, or underscores, starting with a letter." };
  }

  try {
    const host = await freemcHost();
    const outcome = await withServerSsh(host, async (conn) => {
      const ready = await ensureLuckPermsReady(conn, owned.row.containerName);
      if (!ready.ok) return ready;
      const rcon = await sendRcon(conn, owned.row.containerName, user.id, `lp creategroup ${name}`);
      if (!rcon.ok) return { ok: false as const, error: rcon.error };
      const files = await pollUntil(
        () => readYamlStorageDir(conn, owned.row.containerName, LP_GROUPS_DIR),
        (fs) => fs.some((f) => f.key === name),
      );
      if (!files.some((f) => f.key === name)) return { ok: false as const, error: "Role wasn't created — please try again." };
      return { ok: true as const };
    });
    if (!outcome.ok) return { error: outcome.error };
  } catch (e) {
    console.error("[freemc-roles] create failed:", e);
    return { error: "Couldn't reach your server — is it asleep? Connect first to wake it up." };
  }
  revalidatePath("/dashboard/free-minecraft");
  return {};
}

export async function deleteFreemcRole(_prev: unknown, formData: FormData): Promise<Result> {
  const user = await requireUser();
  const owned = await requireOwnedPluginServer(user);
  if (!owned.ok) return { error: owned.error };

  const rl = checkRateLimit(`freemc:roles:delete:${user.id}`, { max: 10, windowMs: 60_000 });
  if (!rl.ok) return { error: `Too many attempts — try again in ${rl.retryAfterSec}s.` };

  const name = String(formData.get("name") ?? "").trim().toLowerCase();
  if (!ROLE_NAME_RE.test(name) || RESERVED_ROLE_NAMES.has(name)) {
    return { error: "Unknown role." };
  }

  try {
    const host = await freemcHost();
    const outcome = await withServerSsh(host, async (conn) => {
      const ready = await ensureLuckPermsReady(conn, owned.row.containerName);
      if (!ready.ok) return ready;
      const rcon = await sendRcon(conn, owned.row.containerName, user.id, `lp deletegroup ${name}`);
      if (!rcon.ok) return { ok: false as const, error: rcon.error };
      const files = await pollUntil(
        () => readYamlStorageDir(conn, owned.row.containerName, LP_GROUPS_DIR),
        (fs) => !fs.some((f) => f.key === name),
      );
      if (files.some((f) => f.key === name)) return { ok: false as const, error: "Role wasn't deleted — please try again." };
      return { ok: true as const };
    });
    if (!outcome.ok) return { error: outcome.error };
  } catch (e) {
    console.error("[freemc-roles] delete failed:", e);
    return { error: "Couldn't reach your server — is it asleep? Connect first to wake it up." };
  }
  revalidatePath("/dashboard/free-minecraft");
  return {};
}

export async function setFreemcRolePermission(_prev: unknown, formData: FormData): Promise<Result> {
  const user = await requireUser();
  const owned = await requireOwnedPluginServer(user);
  if (!owned.ok) return { error: owned.error };

  const rl = checkRateLimit(`freemc:roles:perm:${user.id}`, { max: 30, windowMs: 60_000 });
  if (!rl.ok) return { error: `Too many attempts — try again in ${rl.retryAfterSec}s.` };

  const role = String(formData.get("role") ?? "").trim().toLowerCase();
  const node = String(formData.get("node") ?? "").trim();
  const enabled = String(formData.get("enabled") ?? "") === "true";
  if (!ROLE_NAME_RE.test(role) || RESERVED_ROLE_NAMES.has(role)) return { error: "Unknown role." };
  // The one hard security boundary in this whole feature: a permission node
  // is never taken from free text. Only nodes this codebase has actually
  // confirmed exist and are meaningfully gate-able (freemc-command-catalog.ts)
  // can ever reach an RCON command — anything else is refused outright.
  if (!isGateableCommandNode(node)) return { error: "Unsupported command." };

  try {
    const host = await freemcHost();
    const outcome = await withServerSsh(host, async (conn) => {
      const ready = await ensureLuckPermsReady(conn, owned.row.containerName);
      if (!ready.ok) return ready;
      const groups = await readYamlStorageDir(conn, owned.row.containerName, LP_GROUPS_DIR);
      if (!groups.some((g) => g.key === role)) return { ok: false as const, error: "Unknown role." };

      // "off" unsets the node entirely (removes it) rather than setting it to
      // an explicit `false` — LuckPerms stores an explicit false as a nested
      // `- node:\n    value: false` entry rather than a plain list item;
      // unsetting keeps every role's file in the simple bare-list shape and
      // avoids that representation ambiguity for no functional difference
      // (an unset node and an explicitly-false node both fail to grant it).
      const verb = enabled ? "permission set" : "permission unset";
      const cmd = enabled ? `lp group ${role} ${verb} ${node} true` : `lp group ${role} ${verb} ${node}`;
      const rcon = await sendRcon(conn, owned.row.containerName, user.id, cmd);
      if (!rcon.ok) return { ok: false as const, error: rcon.error };

      const check = await pollUntil(
        async () => {
          const files = await readYamlStorageDir(conn, owned.row.containerName, LP_GROUPS_DIR);
          const file = files.find((f) => f.key === role);
          return file ? parseLuckPermsFile(file.text).permissions.includes(node) : false;
        },
        (granted) => granted === enabled,
      );
      if (check !== enabled) return { ok: false as const, error: "That change didn't take — please try again." };
      return { ok: true as const };
    });
    if (!outcome.ok) return { error: outcome.error };
  } catch (e) {
    console.error("[freemc-roles] set permission failed:", e);
    return { error: "Couldn't reach your server — is it asleep? Connect first to wake it up." };
  }
  revalidatePath("/dashboard/free-minecraft");
  return {};
}

export async function assignFreemcRolePlayer(_prev: unknown, formData: FormData): Promise<Result> {
  const user = await requireUser();
  const owned = await requireOwnedPluginServer(user);
  if (!owned.ok) return { error: owned.error };

  const rl = checkRateLimit(`freemc:roles:assign:${user.id}`, { max: 20, windowMs: 60_000 });
  if (!rl.ok) return { error: `Too many attempts — try again in ${rl.retryAfterSec}s.` };

  const player = String(formData.get("player") ?? "").trim();
  const role = String(formData.get("role") ?? "").trim().toLowerCase();
  if (!PLAYER_NAME_RE.test(player)) return { error: "Enter a valid Minecraft username (3-16 letters, numbers, underscores)." };
  if (!ROLE_NAME_RE.test(role) || RESERVED_ROLE_NAMES.has(role)) return { error: "Unknown role." };

  try {
    const host = await freemcHost();
    const outcome = await withServerSsh(host, async (conn) => {
      const ready = await ensureLuckPermsReady(conn, owned.row.containerName);
      if (!ready.ok) return ready;
      const groups = await readYamlStorageDir(conn, owned.row.containerName, LP_GROUPS_DIR);
      if (!groups.some((g) => g.key === role)) return { ok: false as const, error: "Unknown role." };

      const rcon = await sendRcon(conn, owned.row.containerName, user.id, `lp user ${player} parent add ${role}`);
      if (!rcon.ok) return { ok: false as const, error: rcon.error };

      const uuid = offlineUuidFor(player);
      const has = await pollUntil(
        async () => {
          const r = await exec(
            conn,
            `docker exec ${shellQuote(owned.row.containerName)} sh -c 'cat ${shellQuote(`${LP_USERS_DIR}/${uuid}.yml`)} 2>/dev/null'`,
            10_000,
          );
          return r.code === 0 ? parseLuckPermsFile(r.stdout).parents.includes(role) : false;
        },
        (v) => v === true,
      );
      if (!has) return { ok: false as const, error: "Couldn't assign that player — please try again." };
      return { ok: true as const };
    });
    if (!outcome.ok) return { error: outcome.error };
  } catch (e) {
    console.error("[freemc-roles] assign player failed:", e);
    return { error: "Couldn't reach your server — is it asleep? Connect first to wake it up." };
  }
  revalidatePath("/dashboard/free-minecraft");
  return {};
}

export async function removeFreemcRolePlayer(_prev: unknown, formData: FormData): Promise<Result> {
  const user = await requireUser();
  const owned = await requireOwnedPluginServer(user);
  if (!owned.ok) return { error: owned.error };

  const rl = checkRateLimit(`freemc:roles:remove:${user.id}`, { max: 20, windowMs: 60_000 });
  if (!rl.ok) return { error: `Too many attempts — try again in ${rl.retryAfterSec}s.` };

  const player = String(formData.get("player") ?? "").trim();
  const role = String(formData.get("role") ?? "").trim().toLowerCase();
  if (!PLAYER_NAME_RE.test(player)) return { error: "Invalid player name." };
  if (!ROLE_NAME_RE.test(role) || RESERVED_ROLE_NAMES.has(role)) return { error: "Unknown role." };

  try {
    const host = await freemcHost();
    const outcome = await withServerSsh(host, async (conn) => {
      const ready = await ensureLuckPermsReady(conn, owned.row.containerName);
      if (!ready.ok) return ready;

      const rcon = await sendRcon(conn, owned.row.containerName, user.id, `lp user ${player} parent remove ${role}`);
      if (!rcon.ok) return { ok: false as const, error: rcon.error };

      const uuid = offlineUuidFor(player);
      const stillHas = await pollUntil(
        async () => {
          const r = await exec(
            conn,
            `docker exec ${shellQuote(owned.row.containerName)} sh -c 'cat ${shellQuote(`${LP_USERS_DIR}/${uuid}.yml`)} 2>/dev/null'`,
            10_000,
          );
          return r.code === 0 ? parseLuckPermsFile(r.stdout).parents.includes(role) : false;
        },
        (v) => v === false,
      );
      if (stillHas) return { ok: false as const, error: "Couldn't remove that player — please try again." };
      return { ok: true as const };
    });
    if (!outcome.ok) return { error: outcome.error };
  } catch (e) {
    console.error("[freemc-roles] remove player failed:", e);
    return { error: "Couldn't reach your server — is it asleep? Connect first to wake it up." };
  }
  revalidatePath("/dashboard/free-minecraft");
  return {};
}

export { FREEMC_GATEABLE_COMMANDS };

