"use client";

import { useActionState, useEffect, useState, useTransition } from "react";
import {
  listFreemcRoles,
  createFreemcRole,
  deleteFreemcRole,
  setFreemcRolePermission,
  assignFreemcRolePlayer,
  removeFreemcRolePlayer,
  FREEMC_GATEABLE_COMMANDS,
} from "@/lib/actions-freemc-roles";

type Role = {
  name: string;
  permissions: string[];
  members: { uuid: string; name: string | null }[];
};

const PLAYER_NAME_RE = /^[A-Za-z0-9_]{3,16}$/;

/** Shown instead of the roles UI when the server's active preset has no
 *  plugins — LuckPerms (and therefore roles) only exists on plugin-based
 *  game modes. Matches lib/actions-freemc-roles.ts's own server-side gate. */
function PluginsOnlyNotice() {
  return (
    <div className="card">
      <h3 className="font-semibold text-[var(--fg)]">Roles</h3>
      <p className="mt-2 text-sm text-slate-400">
        Available on plugin-based game modes only. Switch to a preset like SkyBlock, Towny, or Prison from the
        Overview tab to use roles and command permissions.
      </p>
    </div>
  );
}

export function RolesTab({ presetKind }: { presetKind: "properties" | "plugins" }) {
  if (presetKind !== "plugins") return <PluginsOnlyNotice />;
  return <RolesManager />;
}

function RolesManager() {
  const [roles, setRoles] = useState<Role[] | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [pending, startTransition] = useTransition();
  const [selectedRole, setSelectedRole] = useState<string | null>(null);

  function refresh() {
    startTransition(async () => {
      const res = await listFreemcRoles();
      if (res.ok) {
        setRoles(res.roles);
        setError(null);
        setSelectedRole((cur) => (cur && res.roles.some((r) => r.name === cur) ? cur : (res.roles[0]?.name ?? null)));
      } else {
        setError(res.error);
        setRoles(null);
      }
    });
  }
  useEffect(() => {
    refresh();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const active = roles?.find((r) => r.name === selectedRole) ?? null;

  return (
    <div className="space-y-6">
      <div className="card">
        <div className="flex items-center justify-between">
          <div>
            <h3 className="font-semibold text-[var(--fg)]">Roles</h3>
            <p className="mt-1 text-sm text-slate-400">
              Create roles, choose which commands they can use, and assign players — powered by LuckPerms.
            </p>
          </div>
          <button type="button" className="btn-ghost text-xs" onClick={refresh} disabled={pending}>
            {pending ? "Refreshing…" : "Refresh"}
          </button>
        </div>
        {error && <p className="mt-3 text-sm text-red-400">{error}</p>}
      </div>

      <CreateRoleForm onDone={refresh} />

      {roles && roles.length === 0 && !error && (
        <div className="card">
          <p className="text-sm text-slate-500">No roles yet — create one above to get started.</p>
        </div>
      )}

      {roles && roles.length > 0 && (
        <div className="card">
          <div className="flex flex-wrap gap-2">
            {roles.map((r) => (
              <button
                key={r.name}
                type="button"
                onClick={() => setSelectedRole(r.name)}
                className={`rounded-xl px-3 py-1.5 text-sm font-medium transition-colors ${
                  selectedRole === r.name
                    ? "bg-gradient-to-r from-accent-blue/90 to-brand-500/90 text-white"
                    : "border border-white/[0.08] text-slate-300 hover:border-white/20"
                }`}
              >
                {r.name}
                <span className="ml-1.5 text-xs opacity-70">({r.members.length})</span>
              </button>
            ))}
          </div>
        </div>
      )}

      {active && <RoleDetail role={active} onDone={refresh} />}
    </div>
  );
}

function CreateRoleForm({ onDone }: { onDone: () => void }) {
  const [state, action, pending] = useActionState(createFreemcRole, {});
  const [name, setName] = useState("");

  useEffect(() => {
    if (!pending && !state.error) onDone();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [pending]);

  return (
    <form
      action={(fd) => {
        action(fd);
      }}
      className="card flex flex-wrap items-end gap-3"
    >
      <div className="flex-1 min-w-[180px]">
        <label className="label">New role name</label>
        <input
          className="input mt-1"
          name="name"
          value={name}
          onChange={(e) => setName(e.target.value.toLowerCase())}
          placeholder="moderator"
          minLength={3}
          maxLength={20}
          pattern="[a-z][a-z0-9_]{2,19}"
          autoComplete="off"
        />
        <p className="mt-1 text-xs text-slate-500">3-20 lowercase letters, numbers, or underscores.</p>
      </div>
      <button className="btn-primary text-sm" disabled={pending || !name}>
        {pending ? "Creating…" : "Create role"}
      </button>
      {state.error && <p className="w-full text-sm text-red-400">{state.error}</p>}
    </form>
  );
}

function RoleDetail({ role, onDone }: { role: Role; onDone: () => void }) {
  return (
    <div className="grid gap-6 lg:grid-cols-2">
      <PermissionsCard role={role} onDone={onDone} />
      <MembersCard role={role} onDone={onDone} />
    </div>
  );
}

function PermissionsCard({ role, onDone }: { role: Role; onDone: () => void }) {
  const [, action] = useActionState(setFreemcRolePermission, {});
  const [busyNode, setBusyNode] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [pending, startTransition] = useTransition();

  const byPlugin = new Map<string, typeof FREEMC_GATEABLE_COMMANDS>();
  for (const cmd of FREEMC_GATEABLE_COMMANDS) {
    if (!byPlugin.has(cmd.plugin)) byPlugin.set(cmd.plugin, []);
    byPlugin.get(cmd.plugin)!.push(cmd);
  }

  function toggle(node: string, currentlyGranted: boolean) {
    setBusyNode(node);
    setError(null);
    const fd = new FormData();
    fd.set("role", role.name);
    fd.set("node", node);
    fd.set("enabled", String(!currentlyGranted));
    startTransition(async () => {
      const res = await setFreemcRolePermission({}, fd);
      setBusyNode(null);
      if (res.error) setError(res.error);
      else onDone();
    });
  }

  return (
    <div className="card">
      <div className="flex items-center justify-between">
        <h4 className="font-semibold text-[var(--fg)]">Commands for {role.name}</h4>
        <DeleteRoleButton role={role.name} onDone={onDone} />
      </div>
      {error && <p className="mt-2 text-sm text-red-400">{error}</p>}
      <div className="mt-4 space-y-4">
        {[...byPlugin.entries()].map(([plugin, cmds]) => (
          <div key={plugin}>
            <p className="text-xs font-semibold uppercase tracking-wide text-slate-500">{plugin}</p>
            <div className="mt-2 space-y-1.5">
              {cmds.map((cmd) => {
                const granted = role.permissions.includes(cmd.node);
                const busy = pending && busyNode === cmd.node;
                return (
                  <label
                    key={cmd.node}
                    className="flex cursor-pointer items-center justify-between gap-3 rounded-lg border border-white/[0.06] px-3 py-2 text-sm hover:border-white/20"
                  >
                    <span className="text-[var(--fg)]">{cmd.label}</span>
                    <input
                      type="checkbox"
                      checked={granted}
                      disabled={busy}
                      onChange={() => toggle(cmd.node, granted)}
                      className="h-4 w-4 accent-brand-500"
                    />
                  </label>
                );
              })}
            </div>
          </div>
        ))}
      </div>
      {/* Keeps useActionState wired even though toggles are dispatched imperatively above. */}
      <form action={action} className="hidden" />
    </div>
  );
}

function DeleteRoleButton({ role, onDone }: { role: string; onDone: () => void }) {
  const [confirming, setConfirming] = useState(false);
  const [pending, startTransition] = useTransition();
  const [error, setError] = useState<string | null>(null);

  function del() {
    setError(null);
    const fd = new FormData();
    fd.set("name", role);
    startTransition(async () => {
      const res = await deleteFreemcRole({}, fd);
      if (res.error) setError(res.error);
      else onDone();
    });
  }

  if (!confirming) {
    return (
      <button type="button" className="btn-ghost text-xs text-red-300" onClick={() => setConfirming(true)}>
        Delete role
      </button>
    );
  }
  return (
    <div className="flex items-center gap-2">
      {error && <span className="text-xs text-red-400">{error}</span>}
      <button type="button" className="btn-ghost text-xs text-red-300" onClick={del} disabled={pending}>
        {pending ? "Deleting…" : "Confirm delete"}
      </button>
      <button type="button" className="btn-ghost text-xs" onClick={() => setConfirming(false)} disabled={pending}>
        Cancel
      </button>
    </div>
  );
}

function MembersCard({ role, onDone }: { role: Role; onDone: () => void }) {
  const [player, setPlayer] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [pending, startTransition] = useTransition();

  function assign() {
    if (!PLAYER_NAME_RE.test(player)) {
      setError("Enter a valid Minecraft username (3-16 letters, numbers, underscores).");
      return;
    }
    setError(null);
    const fd = new FormData();
    fd.set("player", player);
    fd.set("role", role.name);
    startTransition(async () => {
      const res = await assignFreemcRolePlayer({}, fd);
      if (res.error) setError(res.error);
      else {
        setPlayer("");
        onDone();
      }
    });
  }

  function remove(name: string) {
    setError(null);
    const fd = new FormData();
    fd.set("player", name);
    fd.set("role", role.name);
    startTransition(async () => {
      const res = await removeFreemcRolePlayer({}, fd);
      if (res.error) setError(res.error);
      else onDone();
    });
  }

  return (
    <div className="card">
      <h4 className="font-semibold text-[var(--fg)]">Players in {role.name}</h4>
      <p className="mt-1 text-xs text-slate-500">
        Assign by username — the player doesn&apos;t need to be online right now.
      </p>
      <div className="mt-3 flex gap-2">
        <input
          className="input flex-1"
          value={player}
          onChange={(e) => setPlayer(e.target.value)}
          placeholder="PlayerName"
          minLength={3}
          maxLength={16}
          pattern="[A-Za-z0-9_]{3,16}"
          autoComplete="off"
        />
        <button type="button" className="btn-secondary text-sm" onClick={assign} disabled={pending || !player}>
          {pending ? "…" : "Add"}
        </button>
      </div>
      {error && <p className="mt-2 text-sm text-red-400">{error}</p>}
      <ul className="mt-3 space-y-1.5">
        {role.members.length === 0 && <p className="text-sm text-slate-500">No players assigned yet.</p>}
        {role.members.map((m) => (
          <li
            key={m.uuid}
            className="flex items-center justify-between gap-2 rounded-lg border border-white/[0.06] px-3 py-2 text-sm"
          >
            <span className="text-[var(--fg)]">{m.name ?? <span className="text-slate-500">Unknown (never joined)</span>}</span>
            <button type="button" className="btn-ghost text-xs text-red-300" onClick={() => remove(m.name ?? "")} disabled={pending || !m.name}>
              Remove
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}

